```zig
const std = @import("std");
const testing = std.testing;

const rectangles = @import("rectangles.zig");

test "no rows" {
    const strings = [_][]const u8{};
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "no columns" {
    const strings = [_][]const u8{
        "", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "no rectangles" {
    const strings = [_][]const u8{
        " ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "one rectangle" {
    const strings = [_][]const u8{
        "+-+", //
        "| |", //
        "+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "two rectangles without shared parts" {
    const strings = [_][]const u8{
        "  +-+", //
        "  | |", //
        "+-+-+", //
        "| |  ", //
        "+-+  ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2, count);
}

test "five rectangles with shared parts" {
    const strings = [_][]const u8{
        "  +-+", //
        "  | |", //
        "+-+-+", //
        "| | |", //
        "+-+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(5, count);
}

test "rectangle of height 1 is counted" {
    const strings = [_][]const u8{
        "+--+", //
        "+--+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "rectangle of width 1 is counted" {
    const strings = [_][]const u8{
        "++", //
        "||", //
        "++", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "1x1 square is counted" {
    const strings = [_][]const u8{
        "++", //
        "++", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "only complete rectangles are counted" {
    const strings = [_][]const u8{
        "  +-+", //
        "    |", //
        "+-+-+", //
        "| | -", //
        "+-+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "rectangles can be of different sizes" {
    const strings = [_][]const u8{
        "+------+----+", //
        "|      |    |", //
        "+---+--+    |", //
        "|   |       |", //
        "+---+-------+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(3, count);
}

test "corner is required for a rectangle to be complete" {
    const strings = [_][]const u8{
        "+------+----+", //
        "|      |    |", //
        "+------+    |", //
        "|   |       |", //
        "+---+-------+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2, count);
}

test "large input with many rectangles" {
    const strings = [_][]const u8{
        "+---+--+----+", //
        "|   +--+----+", //
        "+---+--+    |", //
        "|   +--+----+", //
        "+---+--+--+-+", //
        "+---+--+--+-+", //
        "+------+  | |", //
        "          +-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(60, count);
}

test "rectangles must have four sides" {
    const strings = [_][]const u8{
        "+-+ +-+", //
        "| | | |", //
        "+-+-+-+", //
        "  | |  ", //
        "+-+-+-+", //
        "| | | |", //
        "+-+ +-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(5, count);
}

test "very large input" {
    const strings = [_][]const u8{
        "      +-----+--------+    +-----+ ", //
        "++---++-----+--------+---++-----++", //
        "||+--++-----+-+-++   |   ||     ||", //
        "|||  ||     +-+-++-+ |   ||     ||", //
        "|||  ||     | | || | |   ||     ||", //
        "||| +++-----+-+-++-+-+---++-+   ||", //
        "||| |||     | | || | |+--++-+-+ ||", //
        "||| +++---+-+-+-++-+-++--++-+ | ||", //
        "||| |||+--+-+-+-+| | |+--++---+ ||", //
        "||| ||||  | | | || | |+-+||     ||", //
        "||+-++++--+-+++-++-+-++-+++---++||", //
        "||  |+++--+-+++-+--+-+| |||   ||||", //
        "+++-+++++---++--+-++-++-+++---+|||", //
        " |+-+++++---++--+ || || |||   ||||", //
        " |  +++++---++--+-++-++-++++  ||||", //
        " |   ||||   |+----++-++-++++--+++|", //
        " |   |+++---+|    || || ||    || |", //
        "+++  |||+---++----+| || ||    || |", //
        "|||  +++----++----++-++-++----++-+", //
        "+++---++----++-----+-++-++----++  ", //
        "                      +-+         ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2063, count);
}

```

```zig
/// Returns the number of rectangles in the ASCII diagram `strings`.
pub fn rectangles(strings: []const []const u8) usize {
    const rows = strings.len;
    if (rows == 0) return 0;
    const cols = strings[0].len;
    if (cols == 0) return 0;

    var count: usize = 0;

    // For each pair of columns (left, right), find rows where both columns
    // have a '+' (corner). For each such pair of rows, check if the horizontal
    // edges between them are complete (all '-' or '+' between left and right).
    var left: usize = 0;
    while (left < cols) : (left += 1) {
        var right: usize = left + 1;
        while (right < cols) : (right += 1) {
            // Collect rows where both left and right columns are corners
            var row_pairs: usize = 0;
            var top: usize = 0;
            while (top < rows) : (top += 1) {
                if (strings[top][left] == '+' and strings[top][right] == '+') {
                    var bottom: usize = top + 1;
                    while (bottom < rows) : (bottom += 1) {
                        if (strings[bottom][left] == '+' and strings[bottom][right] == '+') {
                            // Check top edge
                            var ok = true;
                            var c: usize = left + 1;
                            while (c < right) : (c += 1) {
                                const ch = strings[top][c];
                                if (ch != '-' and ch != '+') {
                                    ok = false;
                                    break;
                                }
                            }
                            if (!ok) continue;
                            // Check bottom edge
                            c = left + 1;
                            while (c < right) : (c += 1) {
                                const ch = strings[bottom][c];
                                if (ch != '-' and ch != '+') {
                                    ok = false;
                                    break;
                                }
                            }
                            if (!ok) continue;
                            // Check left edge
                            var r: usize = top + 1;
                            while (r < bottom) : (r += 1) {
                                const ch = strings[r][left];
                                if (ch != '|' and ch != '+') {
                                    ok = false;
                                    break;
                                }
                            }
                            if (!ok) continue;
                            // Check right edge
                            r = top + 1;
                            while (r < bottom) : (r += 1) {
                                const ch = strings[r][right];
                                if (ch != '|' and ch != '+') {
                                    ok = false;
                                    break;
                                }
                            }
                            if (!ok) continue;
                            count += 1;
                        }
                    }
                }
            }
            _ = row_pairs;
        }
    }

    return count;
}

